import { d as db } from "../../../../../chunks/db.js";
import { fail } from "@sveltejs/kit";
import "../../../../../chunks/formData.js";
import { s as superValidate, z as zod, m as message } from "../../../../../chunks/zod.js";
import { z } from "zod";
const taxaSchema = z.object({
  tipo: z.string().min(1),
  codigo: z.string().min(1),
  regiao: z.string().min(1),
  descricao: z.string().min(1),
  valor: z.coerce.number().min(0, "Valor deve ser maior ou igual a 0"),
  observacao: z.string().optional().nullable()
});
const load = async () => {
  const taxas = await db.taxa.findMany({
    include: {
      _count: {
        select: {
          produtos: true
        }
      }
    }
  });
  const form = await superValidate(zod(taxaSchema));
  return {
    taxas: taxas.map((t) => ({
      ...t,
      valor: t.valor.toNumber()
    })),
    form
  };
};
const actions = {
  create: async ({ request }) => {
    const form = await superValidate(request, zod(taxaSchema));
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      await db.taxa.create({
        data: form.data
      });
      return message(form, "Taxa criada com sucesso!");
    } catch (error) {
      console.error("Error creating tax:", error);
      return fail(500, {
        form,
        error: "Erro ao criar taxa"
      });
    }
  },
  edit: async ({ request, url }) => {
    const form = await superValidate(request, zod(taxaSchema));
    const id = url.searchParams.get("id");
    if (!id) {
      return fail(400, { form, error: "ID da taxa não fornecido" });
    }
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      await db.taxa.update({
        where: { id },
        data: form.data
      });
      return message(form, "Taxa atualizada com sucesso!");
    } catch (error) {
      console.error("Error updating tax:", error);
      return fail(500, {
        form,
        error: "Erro ao atualizar taxa"
      });
    }
  }
};
export {
  actions,
  load
};
